  1 | // New research wizard — 720px centered layout per hifi/screen-new.jsx.
  2 | // Skill-aware: uses SkillPicker + DynamicFormFields from the selected skill's
  3 | // manifest (GET /skills); falls back to a subject/variant free-form pair.
  4 | import { useEffect, useMemo, useState } from 'react';
  5 | import { Link, useNavigate } from 'react-router-dom';
  6 | import { useModels, useStartResearch, useSkills, useSkillFormFields } from '../hooks/useResearch';
  7 | import { Field, Icon } from '../components/hifi/primitives';
  8 | import SkillPicker from '../components/SkillPicker';
  9 | import DynamicFormFields from '../components/DynamicFormFields';
 10 | 
 11 | const FOCUS_EXAMPLES = [
 12 |   'improve robustness',
 13 |   'reduce overfitting',
 14 |   'explore a new dimension',
 15 | ];
 16 | 
 17 | export default function NewResearch() {
 18 |   const navigate = useNavigate();
 19 |   const startMut = useStartResearch();
 20 |   const { data: models } = useModels();
 21 | 
 22 |   const [subject, setSubject] = useState('');
 23 |   const [variant, setVariant] = useState('default');
 24 |   const [tag, setTag] = useState('');
 25 |   const [focusHint, setFocusHint] = useState('');
 26 |   const [maxIterations, setMaxIterations] = useState(30);
 27 |   const [maxBudget, setMaxBudget] = useState(10);
 28 |   const [timeoutMinutes, setTimeoutMinutes] = useState(120);
 29 |   const [quickMode, setQuickMode] = useState(false);
 30 | 
 31 |   // P3-021 / P3-022: skill-aware form state.
 32 |   const { data: skills } = useSkills();
 33 |   const [selectedSkillId, setSelectedSkillId] = useState<string | null>(null);
 34 |   const { data: skillFormFieldsData } = useSkillFormFields(selectedSkillId);
 35 |   const [skillParams, setSkillParams] = useState<Record<string, unknown>>({});
 36 |   const skillFormFields = skillFormFieldsData?.form_fields ?? [];
 37 | 
 38 |   // Default the subject/variant to the selected skill's first enumeration.
 39 |   useEffect(() => {
 40 |     if (!selectedSkillId) return;
 41 |     setSubject((prev) => prev || 'default');
 42 |   }, [selectedSkillId]);
 43 | 
 44 |   // When form fields include subject/variant, sync them into the state.
 45 |   useEffect(() => {
 46 |     if (skillFormFields.length === 0) return;
 47 |     const subjectField = skillFormFields.find((f) => f.name === 'subject_id');
 48 |     const variantField = skillFormFields.find((f) => f.name === 'variant');
 49 |     if (subjectField) {
 50 |       const val = skillParams[subjectField.name];
 51 |       if (typeof val === 'string' && val) setSubject(val);
 52 |     }
 53 |     if (variantField) {
 54 |       const val = skillParams[variantField.name];
 55 |       if (typeof val === 'string' && val) setVariant(val);
 56 |     }
 57 |   }, [skillFormFields, skillParams]);
 58 | 
 59 |   const modelCount = useMemo(() => (models?.length ?? 0), [models]);
 60 | 
 61 |   // Cheap estimates surfaced in the preview row.
 62 |   const estRuntime = useMemo(() => {
 63 |     const perIter = quickMode ? 2 : 6; // minutes
 64 |     const total = maxIterations * perIter;
 65 |     const h = Math.floor(total / 60);
 66 |     const m = total % 60;
 67 |     return h ? `~${h}h ${m}m` : `~${m}m`;
 68 |   }, [maxIterations, quickMode]);
 69 |   const estCost = useMemo(() => Math.min(maxBudget, maxIterations * (quickMode ? 0.04 : 0.24)), [maxIterations, maxBudget, quickMode]);
 70 | 
 71 |   const skillSelected = Boolean(selectedSkillId);
 72 | 
 73 |   const handleStart = (e: React.FormEvent) => {
 74 |     e.preventDefault();
 75 |     if (!skillSelected || !subject) return;
 76 |     startMut.mutate(
 77 |       {
 78 |         skill_id: selectedSkillId ?? undefined,
 79 |         subject_id: subject,
 80 |         variant,
 81 |         skill_params: Object.keys(skillParams).length > 0 ? skillParams : undefined,
 82 |         tag: tag || undefined,
 83 |         quick_mode: quickMode,
 84 |         max_iterations: maxIterations,
 85 |         max_budget_usd: maxBudget,
 86 |         timeout_minutes: timeoutMinutes,
 87 |         focus_hint: focusHint || undefined,
 88 |       },
 89 |       { onSuccess: (session) => navigate(`/research/${session.id}`) },
 90 |     );
 91 |   };
 92 | 
 93 |   return (
 94 |     <div style={{ display: 'grid', placeItems: 'start center', padding: '32px 24px' }}>
 95 |       <div style={{ width: 720, display: 'flex', flexDirection: 'column', gap: 20 }}>
 96 |         <div className="col gap-1">
 97 |           <div className="crumb">
 98 |             <Link to="/">Dashboard</Link>
 99 |             <Icon name="chevR" size={12} />
100 |             <span>New research</span>
101 |           </div>
102 |           <h1 className="h1">Start a new research session</h1>
103 |           <p className="subtle" style={{ maxWidth: 540, lineHeight: 1.5 }}>
104 |             Pick a skill and set its parameters. The agent will explore configurations,
105 |             evaluate gates, and surface promotable candidates.
106 |           </p>
107 |         </div>
108 | 
109 |         <form onSubmit={handleStart} className="col gap-4">
110 |           {/* Required card */}
111 |           <div className="card" style={{ padding: 20, display: 'flex', flexDirection: 'column', gap: 18 }}>
112 |             <div className="row" style={{ justifyContent: 'space-between' }}>
113 |               <div className="col gap-1">
114 |                 <span className="label">required</span>
115 |                 <h2 className="h2">Target</h2>
116 |               </div>
117 |             </div>
118 | 
119 |             {/* P3-021: skill picker selects the installed skill. */}
120 |             <Field label="Skill" required>
121 |               <SkillPicker
122 |                 skills={skills ?? []}
123 |                 selected={selectedSkillId}
124 |                 onSelect={(id) => {
125 |                   setSelectedSkillId(id);
126 |                   setSkillParams({});
127 |                 }}
128 |               />
129 |               {modelCount === 0 && (
130 |                 <span className="subtle" style={{ fontSize: 11 }}>
131 |                   No skills installed — add a package under skills/ and reload.
132 |                 </span>
133 |               )}
134 |             </Field>
135 | 
136 |             {skillFormFields.length > 0 ? (
137 |               /* P3-022: dynamic form fields from the selected skill's manifest */
138 |               <DynamicFormFields
139 |                 fields={skillFormFields}
140 |                 values={skillParams}
141 |                 onChange={(name, value) => setSkillParams((prev) => ({ ...prev, [name]: value }))}
142 |                 skillId={selectedSkillId ?? undefined}
143 |               />
144 |             ) : (
145 |               <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 1fr', gap: 16 }}>
146 |                 <Field label="Subject" required help="The entity this research operates on.">
147 |                   <input
148 |                     className="input mono"
149 |                     value={subject}
150 |                     onChange={(e) => setSubject(e.target.value)}
151 |                     placeholder="e.g. default"
152 |                     required
153 |                   />
154 |                 </Field>
155 |                 <Field label="Variant" required>
156 |                   <input
157 |                     className="input mono"
158 |                     value={variant}
159 |                     onChange={(e) => setVariant(e.target.value)}
160 |                     placeholder="e.g. production"
161 |                     required
162 |                   />
163 |                 </Field>
164 |               </div>
165 |             )}
166 |           </div>
167 | 
168 |           {/* Optional card */}
169 |           <div className="card" style={{ padding: 20, display: 'flex', flexDirection: 'column', gap: 18 }}>
170 |             <div className="col gap-1">
171 |               <span className="label">optional</span>
172 |               <h2 className="h2">Shape the search</h2>
173 |             </div>
174 | 
175 |             <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
176 |               <Field label="Tag">
177 |                 <input className="input mono" value={tag} onChange={(e) => setTag(e.target.value)} placeholder="e.g. sweep-lr" />
178 |               </Field>
179 |               <Field label="Max iterations" help={`hard cap at ${maxIterations}`}>
180 |                 <input
181 |                   className="input mono"
182 |                   type="number"
183 |                   value={maxIterations}
184 |                   onChange={(e) => setMaxIterations(Number(e.target.value))}
185 |                   min={1}
186 |                   max={500}
187 |                 />
188 |               </Field>
189 |             </div>
190 | 
191 |             <Field label="Focus hint" help="Direction for the agent's exploration.">
192 |               <textarea
193 |                 className="textarea"
194 |                 rows={2}
195 |                 value={focusHint}
196 |                 onChange={(e) => setFocusHint(e.target.value)}
197 |                 placeholder="e.g. Improve robustness without inflating cost."
198 |               />
199 |               <div className="row gap-2" style={{ marginTop: 6 }}>
200 |                 {FOCUS_EXAMPLES.map((ex) => (
201 |                   <button
202 |                     type="button"
203 |                     key={ex}
204 |                     className="btn btn--ghost btn--sm"
205 |                     onClick={() => setFocusHint(ex)}
206 |                   >
207 |                     {ex}
208 |                   </button>
209 |                 ))}
210 |               </div>
211 |             </Field>
212 | 
213 |             <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
214 |               <Field label="Max budget (USD)">
215 |                 <input
216 |                   className="input mono"
217 |                   type="number"
218 |                   value={maxBudget}
219 |                   onChange={(e) => setMaxBudget(Number(e.target.value))}
220 |                   min={1}
221 |                   max={500}
222 |                   step={0.5}
223 |                 />
224 |               </Field>
225 |               <Field label="Timeout (min)">
226 |                 <input
227 |                   className="input mono"
228 |                   type="number"
229 |                   value={timeoutMinutes}
230 |                   onChange={(e) => setTimeoutMinutes(Number(e.target.value))}
231 |                   min={30}
232 |                   max={1440}
233 |                   step={30}
234 |                 />
235 |               </Field>
236 |             </div>
237 | 
238 |             <label className={`check ${quickMode ? 'on' : ''}`}>
239 |               <span className="check__box" onClick={() => setQuickMode(!quickMode)} />
240 |               <span>Quick mode (fewer iterations, reduced sample size)</span>
241 |             </label>
242 |           </div>
243 | 
244 |           {/* Preview row */}
245 |           <div
246 |             className="card card--raised"
247 |             style={{
248 |               padding: 16,
249 |               display: 'grid',
250 |               gridTemplateColumns: 'repeat(4, 1fr)',
251 |               gap: 12,
252 |             }}
253 |           >
254 |             <PreviewItem label="estimated runtime" value={estRuntime} />
255 |             <PreviewItem label="estimated cost" value={`~$${estCost.toFixed(2)}`} />
256 |             <PreviewItem label="iteration cap" value={`${maxIterations}`} />
257 |             <PreviewItem label="mode" value={quickMode ? 'quick' : 'standard'} />
258 |           </div>
259 | 
260 |           {/* Actions */}
261 |           <div className="row" style={{ justifyContent: 'space-between' }}>
262 |             <button
263 |               type="button"
264 |               className="btn btn--ghost"
265 |               onClick={() => navigate('/')}
266 |             >
267 |               Cancel
268 |             </button>
269 |             <div className="row gap-2">
270 |               <button type="button" className="btn btn--ghost" disabled>
271 |                 Save as draft
272 |               </button>
273 |               <button
274 |                 type="submit"
275 |                 className="btn btn--solid"
276 |                 disabled={startMut.isPending || !skillSelected || !subject}
277 |               >
278 |                 {startMut.isPending ? 'Starting…' : 'Start research'}
279 |                 <Icon name="arrR" size={12} />
280 |               </button>
281 |             </div>
282 |           </div>
283 |           {startMut.isError && (
284 |             <div className="banner banner--red">{(startMut.error as Error).message}</div>
285 |           )}
286 |         </form>
287 |       </div>
288 |     </div>
289 |   );
290 | }
291 | 
292 | function PreviewItem({ label, value }: { label: string; value: string }) {
293 |   return (
294 |     <div className="col gap-1">
295 |       <span className="label">{label}</span>
296 |       <span className="mono" style={{ fontSize: 14, color: 'var(--fg)' }}>
297 |         {value}
298 |       </span>
299 |     </div>
300 |   );
301 | }

 1 | // Skill plugin renderer registry (ARC-011 P3-028).
 2 | //
 3 | // A skill plugin renders form fields (or other skill-specific UI surfaces) that
 4 | // the generic components do not understand out of the box. The registry is the
 5 | // extension point: a future skill ships a renderer, registers it, and the
 6 | // DynamicFormFields component picks it up without the form component itself
 7 | // gaining a new branch — the same "drop a directory, no UI code changes"
 8 | // guarantee the backend already provides (ARC-011 §7.14).
 9 | //
10 | // The registry is intentionally tiny and synchronous. Plugin discovery is the
11 | // app's responsibility (import + register at module load); the registry only
12 | // resolves a renderer for a given field at render time. A generic fallback
13 | // renderer (render-as-text + warning) is seeded so an unknown field type never
14 | // breaks the form — the P3-028 "generic fallback" AC.
15 | import type { FormField } from '../api/client';
16 | import type { ReactNode } from 'react';
17 | 
18 | /**
19 |  * Props passed to a skill plugin renderer. Mirrors the FieldInput contract so
20 |  * a plugin is a drop-in replacement for the built-in field controls.
21 |  */
22 | export interface SkillPluginRendererProps {
23 |   field: FormField;
24 |   /** Current value (already resolved: row value, else default, else ''). */
25 |   value: unknown;
26 |   onChange: (value: unknown) => void;
27 | }
28 | 
29 | /**
30 |  * A renderer for one or more field types. Registered against the plugin
31 |  * registry; the first renderer whose `canRender` returns true wins.
32 |  */
33 | export interface SkillPluginRenderer {
34 |   /** Stable id for diagnostics (e.g. "rl-hpo-matrix"). */
35 |   id: string;
36 |   /** Whether this renderer handles the given field. */
37 |   canRender: (field: FormField) => boolean;
38 |   /** Render the field control. */
39 |   render: (props: SkillPluginRendererProps) => ReactNode;
40 | }

