563 | /** Trigger a browser file download from an API endpoint. */
564 | async function triggerDownload(url: string): Promise<void> {
565 |   const res = await fetch(url, { headers: withAuthHeaders() });
566 |   if (!res.ok) {
567 |     const body = await res.text();
568 |     throw new Error(`${res.status}: ${body}`);
569 |   }
570 |   const blob = await res.blob();
571 |   const disposition = res.headers.get('Content-Disposition');
572 |   let filename = 'download';
573 |   if (disposition) {
574 |     const match = disposition.match(/filename="?([^"]+)"?/);
575 |     if (match) filename = match[1];
576 |   }
577 |   const a = document.createElement('a');
578 |   a.href = URL.createObjectURL(blob);
579 |   a.download = filename;
580 |   document.body.appendChild(a);
581 |   a.click();
582 |   a.remove();
583 |   URL.revokeObjectURL(a.href);
584 | }
