 14 | // Key secondary metrics worth charting per model type.
 15 | // Manifest chart_series (metric_schema.chart_series) are the primary source;
 16 | // when absent, the first numeric secondary metrics observed in the iterations
 17 | // are used as a generic fallback (P3-024).
 18 | const DEFAULT_COLORS = ['#34D399', '#FBBF24', '#F472B6', '#60A5FA', '#F87171', '#A78BFA'];
 19 | 
 20 | function fallbackSeries(iterations: Iteration[]): { key: string; label: string; color: string }[] {
 21 |   const seen = new Set<string>();
 22 |   for (const it of iterations) {
 23 |     const sm = it.secondary_metrics;
 24 |     if (!sm) continue;
 25 |     for (const key of Object.keys(sm)) {
 26 |       const value = sm[key]?.value;
 27 |       if (typeof value === 'number') seen.add(key);
 28 |       if (seen.size >= 3) break;
 29 |     }
 30 |     if (seen.size >= 3) break;
 31 |   }
 32 |   return Array.from(seen).map((key, i) => ({
 33 |     key,
 34 |     label: key,
 35 |     color: DEFAULT_COLORS[i % DEFAULT_COLORS.length],
 36 |   }));
 37 | }
 38 | 
 39 | function trainingGatesPassed(iteration: Iteration): boolean {
 40 |   return iteration.training_gates_passed ?? iteration.all_gates_passed;
 41 | }
