 43 | export default function MetricsChart({ iterations, selectedIteration = null, onSelectIteration, chartSeries }: Props) {
 44 | 
 45 |   // P3-024: manifest-driven chart series take priority over the hardcoded
 46 |   // per-model-type fallback. When chartSeries is provided (from
 47 |   // metric_schema.chart_series via the skill descriptor), use it; otherwise
 48 |   // fall back to the legacy detection so existing sessions still render.
 49 |   const secondaryDefs = chartSeries && chartSeries.length > 0
 50 |     ? chartSeries.map((col, i) => ({
 51 |         key: col.field,
 52 |         label: col.label,
 53 |         color: DEFAULT_COLORS[i % DEFAULT_COLORS.length],
 54 |       }))
 55 |     : fallbackSeries(iterations);
 56 |   const [enabledLines, setEnabledLines] = useState<Set<string>>(new Set(['metric']));
 57 | 
 58 |   const data = iterations.map((it) => {
 59 |     const point: Record<string, unknown> = {
 60 |       iteration: it.iteration,
 61 |       metric: it.primary_metric,
 62 |       name: it.metric_name,
 63 |       passed: trainingGatesPassed(it),
 64 |     };
 65 |     for (const def of secondaryDefs) {
 66 |       const sm = it.secondary_metrics?.[def.key];
 67 |       if (sm) point[def.key] = typeof sm.value === 'number' ? sm.value : null;
 68 |     }
 69 |     return point;
 70 |   });
 71 | 
 72 |   if (data.length === 0) {
 73 |     return <div className="text-gray-500 text-sm py-8 text-center">No iterations yet</div>;
 74 |   }
 75 | 
 76 |   const toggleLine = (key: string) => {
 77 |     setEnabledLines((prev) => {
 78 |       const next = new Set(prev);
 79 |       if (key === 'metric') return prev; // Primary is always on
 80 |       next.has(key) ? next.delete(key) : next.add(key);
 81 |       return next;
 82 |     });
 83 |   };
