 85 |   return (
 86 |     <div>
 87 |       {/* Toggle buttons for secondary metrics */}
 88 |       {secondaryDefs.length > 0 && (
 89 |         <div className="flex gap-2 mb-2 flex-wrap">
 90 |           <span className="text-xs text-gray-500 py-1">Overlay:</span>
 91 |           {secondaryDefs.map((def) => (
 92 |             <button
 93 |               key={def.key}
 94 |               onClick={() => toggleLine(def.key)}
 95 |               className={`text-xs px-2 py-1 rounded border transition-colors ${
 96 |                 enabledLines.has(def.key)
 97 |                   ? 'border-gray-500 text-gray-200 bg-gray-700'
 98 |                   : 'border-gray-700 text-gray-500 hover:border-gray-600'
 99 |               }`}
100 |               style={enabledLines.has(def.key) ? { borderColor: def.color, color: def.color } : undefined}
101 |             >
102 |               {def.label}
103 |             </button>
104 |           ))}
105 |         </div>
106 |       )}
107 |       <div className="h-64">
108 |         <ResponsiveContainer width="100%" height="100%">
109 |           <LineChart data={data} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
110 |             <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
111 |             <XAxis dataKey="iteration" stroke="#9CA3AF" fontSize={12} />
112 |             <YAxis yAxisId="primary" stroke="#9CA3AF" fontSize={12} />
113 |             {enabledLines.size > 1 && <YAxis yAxisId="secondary" orientation="right" stroke="#6B7280" fontSize={10} />}
114 |             <Tooltip
115 |               contentStyle={{ backgroundColor: '#1F2937', border: '1px solid #374151', borderRadius: 8 }}
116 |               labelStyle={{ color: '#D1D5DB' }}
117 |             />
