        f"skill {self._manifest.id!r} declares "
        f"promotion_target.kind={kind!r}, which has no wired "
        "PromotionTarget implementation (file_path / webhook / "
        "registry_api are); refusing to silently downgrade to a "
        "file-path promotion"
    )

